export const getListMessageTracesUrl = (
  projectId: string,
  conversationId: number,
  params?: ListMessageTracesParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/elitea_core/message_traces/prompt_lib/${projectId}/${conversationId}?${stringifiedParams}`
    : `/elitea_core/message_traces/prompt_lib/${projectId}/${conversationId}`;
};

/**
 * The LIGHT projection: labels, ordering and the bounded `attrs` display
 * sidecar. The heavy fields (tool_inputs, tool_output, text, thinking)
 * are detail-only and are fetched one step at a time through
 * getMessageTrace, so rendering a conversation's chips never detoasts
 * them.
 *
 * Rows are ordered by (started_at, id) with null timestamps last. Blank
 * thinking steps — transition markers the runtime emits with an action
 * but no text — are excluded, because the client draws a pin for every
 * row it receives.
 *
 * `total` is null unless include_total=true, so "not counted" stays
 * distinguishable from "counted zero".
 * @summary Trace steps for a conversation — the pin strip under each answer
 */
export const listMessageTraces = async (
  projectId: string,
  conversationId: number,
  params?: ListMessageTracesParams,
  options?: Parameters<typeof eliteaFetch>[1],
): Promise<listMessageTracesResponse> => {
  return eliteaFetch<listMessageTracesResponse>(
    getListMessageTracesUrl(projectId, conversationId, params),
    {
      ...options,
      method: "GET",
    },
  );
};

