/**
 * The light projection plus the heavy fields.
 *
 * `message_group_id` is REQUIRED and is matched together with the step
 * id: it is what confines a numeric step id to the message the caller is
 * reading, so a step from elsewhere is a 404 rather than a body.
 * @summary One trace step in full, fetched on pin expand
 */
export const getMessageTrace = async (
  projectId: string,
  stepId: number,
  params: GetMessageTraceParams,
  options?: Parameters<typeof eliteaFetch>[1],
): Promise<getMessageTraceResponse> => {
  return eliteaFetch<getMessageTraceResponse>(
    getGetMessageTraceUrl(projectId, stepId, params),
    {
      ...options,
      method: "GET",
    },
  );
};

